import { NextRequest, NextResponse } from 'next/server';
import fs from 'fs/promises';
import path from 'path';
import { rateLimit } from '@/lib/rateLimit';

/**
 * Second search tier: FDA devices with regulatory concerns (recalls),
 * from the prebuilt public/data/concerns-devices.json index
 * (generated by scripts/buildConcernsIndex.mjs).
 */

export interface ConcernGroup {
  id: string;
  firm: string;
  device: string;
  recallCount: number;
  openRecalls: number;
  worstClass: string | null;
  latestDate: string | null;
  aiLinked?: string[];
  recalls: Array<{
    classification: string;
    status: string;
    initiated: string;
    terminated: string | null;
    reason: string;
    rootCause: string;
    product: string;
    quantity: string | null;
    distribution: string | null;
    eventNumber: string | null;
  }>;
}

let INDEX: ConcernGroup[] | null = null;

async function loadIndex(): Promise<ConcernGroup[]> {
  if (INDEX === null) {
    let loaded: ConcernGroup[] = [];
    try {
      const filePath = path.join(process.cwd(), 'public', 'data', 'concerns-devices.json');
      loaded = JSON.parse(await fs.readFile(filePath, 'utf8'));
    } catch {
      loaded = [];
    }
    INDEX = loaded;
  }
  return INDEX;
}

function tokenize(q: string): string[] {
  return q.toLowerCase().replace(/[^\w\s]/g, ' ').split(/\s+/).filter(t => t.length > 1);
}

export async function GET(req: NextRequest) {
  const limited = rateLimit(req, 'concerns-search', 30, 60_000);
  if (limited) return limited;

  const q = req.nextUrl.searchParams.get('q')?.trim() || '';
  const groups = await loadIndex();
  if (!groups.length) {
    return NextResponse.json({ available: false, reason: 'The regulatory concerns index is not built yet.' });
  }

  const terms = tokenize(q);
  let matches: ConcernGroup[];
  if (!terms.length) {
    matches = groups.slice(0, 8);
  } else {
    const scored: Array<{ g: ConcernGroup; score: number }> = [];
    for (const g of groups) {
      const hay = (g.firm + ' ' + g.device + ' ' + g.recalls.map(r => r.reason + ' ' + r.product).join(' ')).toLowerCase();
      let score = 0;
      for (const t of terms) {
        if (g.firm.toLowerCase().includes(t)) score += 3;
        else if (g.device.toLowerCase().includes(t)) score += 3;
        else if (t.length > 3 && hay.includes(t)) score += 1;
      }
      if (score > 0) scored.push({ g, score });
    }
    matches = scored
      .sort((a, b) => b.score - a.score || (b.g.latestDate || '').localeCompare(a.g.latestDate || ''))
      .slice(0, 8)
      .map(s => s.g);
  }

  return NextResponse.json({
    available: true,
    totalIndexed: groups.length,
    results: matches.map(g => ({
      id: g.id,
      firm: g.firm,
      device: g.device,
      recallCount: g.recallCount,
      openRecalls: g.openRecalls,
      worstClass: g.worstClass || null,
      aiLinked: g.aiLinked || [],
      latestDate: g.latestDate,
      topReasons: Array.from(new Set(g.recalls.map(r => r.reason))).slice(0, 2),
      link: '/device/concern/' + g.id,
    })),
  });
}
